export function createCpuSubmissionPayload(): CpuBenchmarkSubmissionPayload {
  return {
    benchmarkKind: "cpu",
    benchmarkVersion: BENCHMARK_VERSION,
    deviceProfile: createDeviceProfile(),
    result: createCpuResultFixture(),
  };
}

export function createGpuSubmissionPayload(): GpuBenchmarkSubmissionPayload {
  return {
    benchmarkKind: "gpu",
    benchmarkVersion: BENCHMARK_VERSION,
    deviceProfile: createDeviceProfile(),
    result: createGpuResultFixture(),
  };
}

export function createPersistedCpuResultFixture(): PersistedCpuBenchmarkResult {
  const payload = createCpuSubmissionPayload();

  return Object.assign({}, payload.result, {
    id: "fixture-cpu-result-id",
    benchmarkVersion: payload.benchmarkVersion,
    createdAt: new Date().toISOString(),
    browserName: payload.deviceProfile.browser.name,
    browserVersion: payload.deviceProfile.browser.version,
    osPlatform: payload.deviceProfile.browser.os,
    deviceProfile: payload.deviceProfile,
    user: null,
  }) as PersistedCpuBenchmarkResult;
}

export function createPersistedGpuResultFixture(): PersistedGpuBenchmarkResult {
  const payload = createGpuSubmissionPayload();

  return Object.assign({}, payload.result, {
    id: "fixture-gpu-result-id",
    benchmarkVersion: payload.benchmarkVersion,
    createdAt: new Date().toISOString(),
    browserName: payload.deviceProfile.browser.name,
    browserVersion: payload.deviceProfile.browser.version,
    osPlatform: payload.deviceProfile.browser.os,
    deviceProfile: payload.deviceProfile,
    user: null,
  }) as PersistedGpuBenchmarkResult;
}
